            primes.append(n)

    solutions = []
    for i, p in enumerate(primes):
        for j in range(i):
            q = primes[j]
            if p <= q:
                continue
            A = p + q
            B = p - q
            # num = A**A * B**B - 1
            # den = A**B * B**A - 1
            try:
                num = (A**A) * (B**B) - 1
                den = (A**B) * (B**A) - 1
