import json

def solve():
    words = [
        "medea", "oversimplifications", "clonic", "chaplin", "kennan", 
        "postpone", "squabble", "ipsilateral", "misunderstandings", "ussr", 
        "canal", "modifications", "referring", "counterrevolutionaries", 
        "pyridine", "cameroon", "avalanche", "rationalizations", "fortran", 
        "cram", "coachman"
    ]

    # Custom alphabet: standard English minus 'c' and 'm', then 'c' and 'm' at the end.
    # Standard: a b c d e f g h i j k l m n o p q r s t u v w x y z
    # Remove c and m: a b d e f g h i j k l n o p q r s t u v w x y z
    # Append c and m: a b d e f g h i j k l n o p q r s t u v w x y z c m

    std = "abcdefghijklmnopqrstuvwxyz"
    rem = [ch for ch in std if ch not in ('c', 'm')]
    custom_order = rem + ['c', 'm']

    rank = {ch: i for i, ch in enumerate(custom_order)}

    def word_key(w):
        return tuple(rank[ch] for ch in w)

    sorted_words = sorted(words, key=word_key)
    final_answer = ", ".join(sorted_words)

    evidence = {
        "custom_alphabet": "".join(custom_order),
        "sorted_words": sorted_words
    }

    print(json.dumps({
        "final_answer": final_answer,
        "evidence": evidence
    }))

if __name__ == '__main__':
    solve()
